import type { RuntimeLayoutNode } from './layout.js';
import type { WebMenuConfiguration } from './menu-model.js';

type MenuLayoutConfiguration = Pick<
  WebMenuConfiguration,
  'orientation' | 'collapsed' | 'mobileBreakpoint' | 'appearance'
>;

function record(value: unknown): Readonly<Record<string, unknown>> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
    ? (value as Readonly<Record<string, unknown>>)
    : {};
}
/** Snapshot inline margins before creating immutable runtime layout projections. */
export function readWebMenuMargins(
  element: HTMLElement,
): Partial<Record<'marginTop' | 'marginRight' | 'marginBottom' | 'marginLeft', number>> {
  const margins: Partial<
    Record<'marginTop' | 'marginRight' | 'marginBottom' | 'marginLeft', number>
  > = {};
  for (const name of ['marginTop', 'marginRight', 'marginBottom', 'marginLeft'] as const) {
    const value = Number.parseFloat(element.style[name]);
    if (Number.isFinite(value)) margins[name] = value;
  }
  return margins;
}

/** Transient footprint; saved dimensions and responsive rules remain unchanged. */
export function projectWebMenuLayout<T extends RuntimeLayoutNode>(
  node: T,
  viewportWidth: number,
  configuration?: MenuLayoutConfiguration,
  embedded = node.menuEmbedded === true,
  viewportHeight = Number.POSITIVE_INFINITY,
): T {
  if (!node.layout) return node;
  const config = configuration ?? record(node.props?.configuration);
  const mobile = viewportWidth < 768;
  const vertical = config.orientation !== 'horizontal';
  const collapsed = vertical && !mobile && config.collapsed === true;
  const appearance = record(config.appearance);
  const collapsedWidth =
    typeof appearance.collapsedWidth === 'number' ? appearance.collapsedWidth : 72;
  const preferredHeight =
    node.bounds.height === 640 && node.layout.item.height !== 'fixed' ? 80 : node.bounds.height;
  const savedMargin = node.props?.margin;
  const margin = embedded
    ? 0
    : typeof savedMargin === 'number' && Number.isFinite(savedMargin)
      ? savedMargin
      : 0;
  const sideMargin = (name: string): number => {
    const value = node.props?.[name];
    return embedded ? 0 : typeof value === 'number' && Number.isFinite(value) ? value : margin;
  };
  const marginTop = sideMargin('marginTop'),
    marginRight = sideMargin('marginRight'),
    marginBottom = sideMargin('marginBottom'),
    marginLeft = sideMargin('marginLeft');
  const availableWidth = Math.max(0, viewportWidth - marginLeft - marginRight);
  const availableHeight = Math.max(0, viewportHeight - marginTop - marginBottom);
  return {
    ...node,
    bounds: {
      ...node.bounds,
      x: 0,
      y: 0,
      width: collapsed ? collapsedWidth : node.bounds.width,
      height: mobile ? 48 : vertical ? node.bounds.height : preferredHeight,
    },
    props: {
      ...node.props,
      placement: embedded ? 'in-flow' : 'floating',
      floatingHorizontalAnchor:
        node.props?.floatingHorizontalAnchor === 'right' ||
        node.props?.floatingHorizontalAnchor === 'center'
          ? node.props.floatingHorizontalAnchor
          : 'left',
      floatingVerticalAnchor:
        node.props?.floatingVerticalAnchor === 'bottom' ||
        node.props?.floatingVerticalAnchor === 'center'
          ? node.props.floatingVerticalAnchor
          : 'top',
      margin: margin,
      marginTop,
      marginRight,
      marginBottom,
      marginLeft,
      floatingZIndex: 1000,
    },
    layout: {
      ...node.layout,
      item: {
        ...node.layout.item,
        width: embedded ? 'stretch' : vertical && !mobile ? 'fixed' : 'stretch',
        height: mobile ? 'fixed' : embedded ? 'stretch' : vertical ? 'stretch' : 'fixed',
        minWidth: collapsed ? 0 : Math.min(node.layout.item.minWidth ?? 0, availableWidth),
        maxWidth: Number.isFinite(availableWidth)
          ? Math.min(
              collapsed ? availableWidth : (node.layout.item.maxWidth ?? availableWidth),
              availableWidth,
            )
          : collapsed
            ? null
            : node.layout.item.maxWidth,
        minHeight: mobile ? 0 : Math.min(node.layout.item.minHeight ?? 0, availableHeight),
        maxHeight: Number.isFinite(availableHeight)
          ? Math.min(
              mobile ? availableHeight : (node.layout.item.maxHeight ?? availableHeight),
              availableHeight,
            )
          : mobile
            ? null
            : node.layout.item.maxHeight,
        grow: embedded && !mobile ? 1 : 0,
        shrink: false,
        horizontalAnchor: 'start',
        verticalAnchor: 'start',
        left: 0,
        right: 0,
        top: 0,
        bottom: 0,
      },
    },
  };
}

export interface RuntimeReusableMenuDefinition {
  readonly rootComponentId: string;
  readonly components: readonly (RuntimeLayoutNode & { readonly id: string })[];
}
/** A full-height sidebar becomes an intrinsic trigger rather than an invisible full-height hit area on mobile. */
export function projectReusableMenuLayout<T extends RuntimeLayoutNode>(
  placement: T,
  definition: RuntimeReusableMenuDefinition | undefined,
  viewportWidth: number,
  configuration?: MenuLayoutConfiguration,
  viewportHeight = Number.POSITIVE_INFINITY,
): T {
  const menu = reusableMenuNode(definition);
  if (!menu) return placement;
  return projectWebMenuLayout(
    placement,
    viewportWidth,
    configuration ?? (record(menu.props?.configuration) as unknown as MenuLayoutConfiguration),
    false,
    viewportHeight,
  );
}

export function reusableMenuNode(
  definition: RuntimeReusableMenuDefinition | undefined,
): (RuntimeLayoutNode & { readonly id: string }) | undefined {
  if (!definition || !Array.isArray(definition.components)) return undefined;
  const root = definition.components.find(
    (node) => node !== null && typeof node === 'object' && node.id === definition.rootComponentId,
  );
  if (root?.type !== 'WebPanel' || !Array.isArray(root.children) || root.children.length !== 1)
    return undefined;
  const menu = definition.components.find(
    (node) => node !== null && typeof node === 'object' && node.id === root.children?.[0],
  );
  return menu?.type === 'WebMenu' ? menu : undefined;
}

menu-popovers.ts:
/** Expanded horizontal branches use the browser top layer, outside ancestor clipping and stacking contexts. */
export function bindWebMenuPopovers(menu: HTMLElement): () => void {
  const view = menu.ownerDocument.defaultView;
  if (!view || !menu.isConnected || menu.getClientRects().length === 0) return () => undefined;
  const flyouts: HTMLElement[] = [];
  for (const submenu of menu.querySelectorAll<HTMLElement>('.wr-menu-submenu')) {
    if (submenu.hidden || submenu.parentElement?.closest('.wr-menu-submenu[hidden]')) continue;
    submenu.classList.add('wr-menu-flyout');
    submenu.popover = 'manual';
    submenu.showPopover();
    flyouts.push(submenu);
  }
  const place = (): void => {
    const viewport = view.visualViewport;
    const left = (viewport?.offsetLeft ?? 0) + 8;
    const top = (viewport?.offsetTop ?? 0) + 8;
    const right = left + (viewport?.width ?? view.innerWidth) - 16;
    const bottom = top + (viewport?.height ?? view.innerHeight) - 16;
    const clamp = (value: number, start: number, end: number): number =>
      Math.max(start, Math.min(value, Math.max(start, end)));
    for (const submenu of flyouts) {
      const line = submenu.parentElement?.querySelector<HTMLElement>(':scope > .wr-menu-line');
      if (!line) continue;
      submenu.style.maxWidth = `${Math.max(0, right - left)}px`;
      submenu.style.maxHeight = `${Math.max(0, bottom - top)}px`;
      const anchor = line.getBoundingClientRect();
      const size = submenu.getBoundingClientRect();
      const nested = line.closest('.wr-menu-submenu') !== null;
      const availableAfter = nested ? right - anchor.right : bottom - anchor.bottom;
      const availableBefore = nested ? anchor.left - left : anchor.top - top;
      const flip =
        availableAfter < (nested ? size.width : size.height) + 6 &&
        availableBefore > availableAfter;
      const x = nested ? (flip ? anchor.left - size.width - 6 : anchor.right + 6) : anchor.left;
      const y = nested ? anchor.top : flip ? anchor.top - size.height - 6 : anchor.bottom + 6;
      submenu.style.left = `${clamp(x, left, right - size.width)}px`;
      submenu.style.top = `${clamp(y, top, bottom - size.height)}px`;
      submenu.dataset.openDirection = nested ? (flip ? 'left' : 'right') : flip ? 'up' : 'down';
    }
  };
  place();
  const observer =
    typeof view.ResizeObserver === 'undefined' ? undefined : new view.ResizeObserver(place);
  observer?.observe(menu);
  flyouts.forEach((element) => observer?.observe(element));
  view.addEventListener('resize', place);
  view.addEventListener('scroll', place, true);
  view.visualViewport?.addEventListener('resize', place);
  view.visualViewport?.addEventListener('scroll', place);
  return () => {
    observer?.disconnect();
    view.removeEventListener('resize', place);
    view.removeEventListener('scroll', place, true);
    view.visualViewport?.removeEventListener('resize', place);
    view.visualViewport?.removeEventListener('scroll', place);
    for (const submenu of flyouts) {
      if (submenu.matches(':popover-open')) submenu.hidePopover();
    }
  };
}

reusable-menu-layout.ts:
import { setRuntimeLayoutProjection } from './layout.js';
import {
  projectReusableMenuLayout,
  readWebMenuMargins,
  type RuntimeReusableMenuDefinition,
} from './menu-layout.js';
import type { WebMenu } from './menu.js';
import { bindWebMenuEventHost } from './menu-events.js';

/** Keep the reusable shell in sync with the responsive state of its full-height menu. */
export function bindReusableMenuLayout(
  element: HTMLElement,
  definition: RuntimeReusableMenuDefinition,
  menu: WebMenu,
): () => void {
  const unbindEvents = bindWebMenuEventHost(menu.element, element);
  element.dataset.menuManaged = 'true';
  const view = element.ownerDocument.defaultView;
  const update = (): void => {
    const width = view?.innerWidth ?? 1024;
    const height = view?.innerHeight;
    const configuration = menu.configuration;
    const horizontal = element.dataset.webradFloatingHorizontalAnchor;
    const vertical = element.dataset.webradFloatingVerticalAnchor;
    const margins = readWebMenuMargins(element);
    setRuntimeLayoutProjection(element, (node) =>
      projectReusableMenuLayout(
        {
          ...node,
          props: {
            ...node.props,
            ...margins,
            floatingHorizontalAnchor: horizontal ?? node.props?.floatingHorizontalAnchor,
            floatingVerticalAnchor: vertical ?? node.props?.floatingVerticalAnchor,
          },
        },
        definition,
        width,
        configuration,
        height,
      ),
    );
  };
  const onMenuLayout = (event: Event): void => {
    if (event.target === menu.element) update();
  };
  update();
  element.addEventListener('webrad:menu-layout-change', onMenuLayout);
  element.addEventListener('webrad-placement-change', update);
  view?.addEventListener('resize', update);
  const observer =
    typeof view?.MutationObserver === 'undefined' ? undefined : new view.MutationObserver(update);
  observer?.observe(element, { attributes: true, attributeFilter: ['style'] });
  return () => {
    unbindEvents();
    observer?.disconnect();

    delete element.dataset.menuManaged;

    element.removeEventListener('webrad:menu-layout-change', onMenuLayout);
    element.removeEventListener('webrad-placement-change', update);
    view?.removeEventListener('resize', update);
    setRuntimeLayoutProjection(element, null);
  };
}

